from pptx import Presentation
import io

def inspect_pptx(path):
    prs = Presentation(path)
    for i, slide in enumerate(prs.slides):
        print(f"Slide {i+1}")
        for shape in slide.shapes:
            print(f"  Shape: {shape.name}, Type: {shape.shape_type}")
            if shape.has_text_frame:
                print(f"    Text: {shape.text}")
            if shape.shape_type == 7: # Graphic Frame
                if shape.has_table:
                    print("    Has Table")
                else:
                    # Check for embedded object
                    try:
                        obj = shape.ole_format
                        print(f"    Embedded Object: {obj.prog_id}")
                    except:
                        pass

inspect_pptx('input.pptx')

